INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62089855', 62089855, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Kardus File, Amplop Coklat Kecil Kop, Amplop Coklat Sedang Kop, Map Inspektorat Jenderal, Map Konsep Laporan Pemeriksaan Rutin, Map Konsep Laporan Pemeriksaan Khusus Dalam Memenuhi Keperluan Perkantoran Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 69600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pekerjaan ini mencakup pengadaan barang persediaan konsumsi perkantoran untuk memenuhi kebutuhan administrasi dan tata kelola dokumen pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 yang dilaksanakan dalam 1 (satu) Tahun Anggaran. Pengadaan dilakukan secara berkala sesuai rencana kebutuhan tahunan guna menjamin ketersediaan perlengkapan administrasi secara berkesinambungan, yang terdiri atas Kardus File sebanyak 600 buah, Amplop Coklat Kecil berkop sebanyak 600 buah, Amplop Coklat Sedang berkop sebanyak 600 buah, Map Inspektorat Jenderal sebanyak 1.200 buah, Map Konsep Laporan Pemeriksaan Rutin sebanyak 600 buah, serta Map Konsep Laporan Pemeriksaan Khusus sebanyak 600 buah. Ruang lingkup pekerjaan meliputi penyediaan dan pengiriman seluruh barang sesuai jumlah dan periode kebutuhan yang telah ditetapkan, dengan ketentuan barang dalam kondisi baru, layak pakai, dan memenuhi standar mutu perlengkapan perkantoran.', 'enis barang yang disediakan meliputi kardus file, amplop coklat kecil berkop, amplop coklat sedang berkop, map Inspektorat Jenderal, map konsep laporan pemeriksaan rutin, dan map konsep laporan pemeriksaan khusus. Seluruh barang harus merupakan produk baru, tidak cacat, dan sesuai standar perlengkapan administrasi perkantoran. Jumlah pengadaan disesuaikan dengan kebutuhan bulanan selama 1 (satu) tahun anggaran sebagaimana rencana kebutuhan yang telah ditetapkan. Barang wajib disediakan sesuai volume dan satuan yang tercantum dalam kontrak serta dapat diserahkan secara bertahap atau sekaligus sesuai permintaan pengguna.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 180091);
