INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62086292', 62086292, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Langganan Jaringan Internet / Bandwidth Kantor Line Pada Kantor Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 432000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '12.0 Bulan', 'Pekerjaan ini meliputi penyediaan layanan langganan jaringan internet atau bandwidth kantor line untuk mendukung pelaksanaan tugas dan fungsi Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Layanan disediakan secara berkesinambungan selama masa kontrak guna menjamin ketersediaan akses internet yang andal bagi kegiatan operasional perkantoran. Ruang lingkup pekerjaan mencakup penyediaan koneksi internet dedicated atau shared sesuai kebutuhan kantor, aktivasi layanan, penyediaan kapasitas bandwidth yang memadai, serta pemeliharaan jaringan secara berkala. Penyedia wajib menjamin kestabilan koneksi, kecepatan akses, dan tingkat ketersediaan layanan yang mendukung kelancaran komunikasi data dan sistem informasi perkantoran.', 'Layanan langganan jaringan internet atau bandwidth kantor line disediakan selama 12 bulan untuk memenuhi kebutuhan konektivitas data Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 secara andal, aman, dan berkesinambungan. Jenis layanan berupa langganan jaringan internet kantor dengan kapasitas bandwidth tertentu sesuai kebutuhan operasional, baik bersifat dedicated maupun shared. Layanan mencakup penyediaan koneksi aktif selama masa kontrak, pengelolaan bandwidth, serta dukungan akses ke jaringan internet nasional. Kualitas layanan harus menjamin kecepatan akses yang stabil, latensi yang memadai, serta tingkat ketersediaan layanan tinggi untuk mendukung penggunaan aplikasi perkantoran, sistem informasi, komunikasi elektronik, dan pertukaran data. Penyedia wajib menjaga performa jaringan sesuai standar layanan yang disepakati.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 180707);
