INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62086502', 62086502, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN NEGERI KISARAN 03', 'Layanan Bantuan Hukum Perseorangan (Pos Bantuan Hukum)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sumatera Utara, Asahan (Kab.)', 36000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '360 OJ', 'Memberikan informasi, konsultasi, dan advis hukum, bantuan pembuatan dokumen hukum, serta penyediaan informasi daftar Organisasi Bantuan Hukum (OBH) untuk membantu masyarakat kurang mampu mendapatkan bantuan hukum gratis, dengan tujuan pemerataan akses keadilan, meliputi pendampingan, penyelesaian sengketa, dan peningkatan kesadaran hukum, sesuai peraturan perundang-undangan.', '1. Informasi, Konsultasi, dan Advis Hukum: Memberikan penjelasan dan nasihat hukum kepada pencari keadilan yang tidak mampu secara ekonomi, terkait masalah hukum yang mereka hadapi di PN. 2. Bantuan Pembuatan Dokumen Hukum: Membantu menyusun dokumen yang diperlukan, seperti surat gugatan, permohonan, atau dokumen lain yang relevan dengan perkara di pengadilan. 3. Penyediaan Informasi OBH: Memberikan daftar atau informasi mengenai Organisasi Bantuan Hukum (OBH) atau advokat yang dapat memberikan bantuan hukum cuma-cuma secara lebih lanjut. 4. Bantuan Pembebasan Biaya Perkara: Membantu mengurus permohonan pembebasan biaya perkara bagi yang tidak mampu membayar, dengan melampirkan Surat Keterangan Tidak Mampu (SKTM). 5. Pendampingan dan Penyelesaian Sengketa: Memberikan pendampingan di sidang atau membantu proses penyelesaian sengketa di luar sidang, serta meningkatkan kesadaran hukum masyarakat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 181386);
