INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62092274', 62092274, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Sewa Mesin Fotokopi Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 165600000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '30.0 Unit', 'Pekerjaan ini mencakup penyediaan jasa sewa mesin fotokopi untuk mendukung kegiatan administrasi dan operasional perkantoran pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026. Layanan diselenggarakan secara berkesinambungan selama masa kontrak guna menjamin kelancaran penggandaan dokumen kedinasan. Ruang lingkup pekerjaan meliputi penyediaan mesin fotokopi yang layak pakai dan sesuai kebutuhan perkantoran, instalasi dan penempatan mesin pada lokasi yang ditentukan, serta pemeliharaan dan perbaikan mesin selama masa sewa. Penyedia wajib memastikan mesin fotokopi berfungsi dengan baik dan siap digunakan setiap saat. Penyedia bertanggung jawab atas ketersediaan mesin, dukungan teknis, serta penggantian suku cadang dan bahan pendukung apabila diperlukan selama masa kontrak. Apabila terjadi kerusakan atau gangguan, penyedia wajib melakukan penanganan secara cepat agar tidak mengganggu kegiatan perkantoran.', 'Pengadaan ini merupakan jasa sewa mesin fotokopi warna multifungsi untuk mendukung kegiatan operasional perkantoran di lingkungan Inspektorat Jenderal Kementerian Imigrasi. Penyedia wajib menyediakan mesin fotokopi dengan fungsi cetak, salin, pindai, dan faksimile, kecepatan cetak minimal 30 halaman per menit, resolusi minimal 1200 × 1200 dpi, serta mendukung ukuran kertas A3 dan A4. Mesin harus memiliki kapasitas kertas besar, memori dan penyimpanan internal yang memadai, serta mendukung konektivitas USB, jaringan LAN, dan Wi-Fi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 186495);
